  // Caso 1: formato DD/MM/YYYY → "20/12/2025"
  if (fechaStr.includes("/")) {
    const [dia, mes, anio] = fechaStr.split("/");
    return new Date(`${anio}-${mes.padStart(2,"0")}-${dia.padStart(2,"0")}`);
